import "aos/dist/aos.css";
import {
    FaCertificate,
    FaCheckCircle,
    FaClipboardCheck,
    FaIndustry,
    FaComments,
    FaWhatsapp,
} from "react-icons/fa";
import { Certifications1, Certifications2, Certifications3 } from "../../asset/image";
import { useContext } from "react";
import AppContext from "../../../Context";

function Certifications() {
    //-----------------------STATE VIEWS-----------------------//
    const { language } = useContext(AppContext);
    const certificationServices = [
        {
            title: language === "id" ? "Sertifikasi ISO" : "ISO Certification",
            description:
                language === "id"
                    ? "Pendampingan sertifikasi ISO untuk meningkatkan sistem manajemen, kualitas operasional, dan kepercayaan mitra bisnis."
                    : "ISO certification assistance to improve management systems, operational quality, and business partner trust.",
            icon: FaCertificate,
        },
        {
            title: language === "id" ? "Sertifikasi Halal" : "Halal Certification",
            description:
                language === "id"
                    ? "Pendampingan sertifikasi halal sesuai dengan regulasi yang berlaku untuk memastikan kesesuaian produk dan proses."
                    : "Halal certification assistance in accordance with applicable regulations to ensure product and process compliance.",
            icon: FaCheckCircle,
        },
        {
            title:
                language === "id"
                    ? "Sertifikasi & Kepatuhan Bisnis"
                    : "Business & Compliance Certification",
            description:
                language === "id"
                    ? "Pendampingan sertifikasi dan kepatuhan bisnis sesuai dengan standar hukum, industri, dan regulasi."
                    : "Certification and business compliance assistance aligned with legal, industry, and regulatory standards.",
            icon: FaClipboardCheck,
        },
        {
            title:
                language === "id"
                    ? "Sertifikasi Produk & Kualitas"
                    : "Product & Quality Certification",
            description:
                language === "id"
                    ? "Pendampingan sertifikasi kualitas produk untuk meningkatkan daya saing di pasar nasional dan internasional."
                    : "Product quality certification assistance to enhance competitiveness in national and international markets.",
            icon: FaIndustry,
        },
        {
            title:
                language === "id"
                    ? "Konsultasi Sertifikasi"
                    : "Certification Consultation",
            description:
                language === "id"
                    ? "Layanan konsultasi komprehensif yang disesuaikan dengan jenis bisnis dan kebutuhan sertifikasi di berbagai sektor industri."
                    : "Comprehensive consultation services tailored to your business type and industry sector certification needs.",
            icon: FaComments,
        },
    ];
    const certificationShowcases = [
        {
            title:
                language === "id"
                    ? "Sertifikasi JPT (Jasa Pengurusan Transportasi)"
                    : "JPT Certification (Freight Forwarding Services)",
            description:
                language === "id"
                    ? "Kolaborasi antara Regarde Certification & Aston Patent untuk memperkuat kepatuhan regulasi dan branding perusahaan PT Nippon Express Indonesia."
                    : "Collaboration between Regarde Certification & Aston Patent to strengthen regulatory compliance and corporate branding for PT Nippon Express Indonesia.",
            image: Certifications1,
            tag:
                language === "id"
                    ? "Sertifikasi Standar"
                    : "Standard Certification",
        },
        {
            title: "ISO 9001:2015 Certification",
            description:
                language === "id"
                    ? "Regarde Certification menyerahkan sertifikat ISO 9001:2015 kepada PT Nippon Express Indonesia atas penerapan Sistem Manajemen Mutu untuk memastikan konsistensi terhadap standar pelanggan dan regulasi serta meningkatkan kepuasan pelanggan."
                    : "Regarde Certification presented the ISO 9001:2015 Certificate to PT Nippon Express Indonesia for implementing a Quality Management System to ensure consistent compliance with customer and regulatory standards while enhancing customer satisfaction.",
            image: Certifications2,
            tag: "ISO Certification",
        },
        {
            title:
                language === "id"
                    ? "Sertifikasi BPOM"
                    : "BPOM Certification",
            description:
                language === "id"
                    ? "Regarde Certification menyerahkan sertifikat izin edar BPOM untuk produk Tepung Bumbu Deris Jempol di Indonesia."
                    : "Regarde Certification presented the BPOM (Indonesian Food and Drug Authority) Distribution Permit Certificate for Tepung Bumbu Deris Jempol product in Indonesia.",
            image: Certifications3,
            tag:
                language === "id"
                    ? "Sertifikasi BPOM"
                    : "BPOM Certification",
        },
    ];
    // const clients = [
    //     { name: "Client 1", logo: Client1 },
    //     { name: "Client 2", logo: Client2 },
    //     { name: "Client 3", logo: Client3 },
    //     { name: "Client 4", logo: Client4 },
    // ];
    const WA_NUMBER = "6281213094426";
    //-----------------------STATE VIEWS-----------------------//

    //------------------------FUNCTIONS------------------------//
    const getWaLink = (serviceName: string) => {
        const rawMessage =
            language === "id"
                ? `Halo Regarde,\nSaya ingin berkonsultasi terkait layanan Certifications – ${serviceName}.\nMohon informasinya. Terima kasih.`
                : `Hello Regarde,\nI would like to inquire about Certifications service – ${serviceName}.\nPlease provide the details. Thank you.`;

        return `https://wa.me/${WA_NUMBER}?text=${encodeURIComponent(rawMessage)}`;
    };
    //------------------------FUNCTIONS------------------------//

    return (
        <div className="pt-24">
            {/* CERTIFICATIONS DETAIL */}
            <section className="pb-24 bg-white" data-aos="zoom-out">
                <div className="w-11/12 md:w-8/12 mx-auto text-center">

                    {/* ICON */}
                    <div className="flex justify-center mb-6">
                        <div className="w-20 h-20 rounded-full bg-primary-blue-100 flex items-center justify-center">
                            <FaCertificate className="text-primary-blue-700 text-4xl" />
                        </div>
                    </div>

                    {/* TITLE */}
                    <h2 className="text-4xl font-black text-primary-black-500 mb-4">
                        {language === "id" ? "Sertifikasi" : "Certifications"}
                    </h2>

                    {/* DESCRIPTION */}
                    <p className="text-gray-600 max-w-2xl mx-auto mb-14">
                        {language === "id"
                            ? "Layanan pendampingan sertifikasi untuk membantu perusahaan memenuhi standar, meningkatkan kredibilitas, dan memperluas peluang bisnis."
                            : "Certification assistance services to help companies meet standards, enhance credibility, and expand business opportunities."}
                    </p>

                    {/* SUB SERVICES */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8 text-left">
                        {certificationServices.map((service, i) => {
                            const Icon = service.icon;
                            return (
                                <div
                                    key={i}
                                    data-aos="fade-up"
                                    data-aos-delay={i * 100}
                                    className="bg-white rounded-xl border border-gray-200 p-6 hover:shadow-md transition flex flex-col"
                                >
                                    {/* CONTENT */}
                                    <div className="flex items-start gap-4">
                                        <div className="text-primary-blue-600 text-2xl mt-1">
                                            <Icon />
                                        </div>
                                        <div>
                                            <h3 className="font-semibold text-primary-black-500">
                                                {service.title}
                                            </h3>
                                            <p className="text-sm text-gray-600 mt-1">
                                                {service.description}
                                            </p>
                                        </div>
                                    </div>

                                    {/* WA BUTTON */}
                                    <a
                                        href={getWaLink(service.title)}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="mt-auto self-end w-10 h-10 rounded-full bg-green-600 text-white flex items-center justify-center hover:bg-green-700 transition"
                                        aria-label="Chat via WhatsApp"
                                    >
                                        <FaWhatsapp className="text-lg" />
                                    </a>
                                </div>
                            );
                        })}
                    </div>

                </div>
            </section>

            {/* CERTIFICATION SHOWCASE */}
            <section className="py-10 ">
                <div className="w-11/12 md:w-9/12 mx-auto">
                    <div className="flex flex-wrap justify-center gap-8">
                        {certificationShowcases.map((item, i) => (
                            <div key={i} data-aos="fade-up" data-aos-delay={i * 100}
                                className=" bg-white rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition flex flex-col overflow-hidden w-full sm:w-[45%] lg:w-[48%] "
                            >
                                <div className="h-96 w-full overflow-hidden">
                                    <img src={item.image} alt={item.title} className="w-full h-full object-cover hover:scale-105 transition duration-500"
                                    />
                                </div>
                                <div className="p-5 flex flex-col flex-grow">
                                    <div className="flex items-center gap-2 mb-3">
                                        <FaCertificate className="text-primary-blue-700 text-sm" />
                                        <span className="text-xs font-semibold text-primary-black-500">
                                            {item.tag}
                                        </span>
                                    </div>
                                    <h4 className="text-lg font-semibold text-primary-black-500 mb-2">
                                        {item.title}
                                    </h4>
                                    <p className="text-sm text-gray-600 leading-relaxed">
                                        {item.description}
                                    </p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </section>

            {/* OUR CLIENTS */}
            {/* <section className="py-10">
                <div className="w-11/12 md:w-9/12 mx-auto text-center">
                    <h2
                        data-aos="zoom-in"
                        className="text-4xl font-black text-primary-blue-900 mb-12">
                        Our Clients
                    </h2>
                    <div className="flex flex-wrap justify-center gap-8">
                        {clients.map((client, i) => (
                            <div key={i}
                                data-aos="fade-up"
                                data-aos-delay={i * 40}
                                className="flex items-center justify-center">
                                <img
                                    src={client.logo}
                                    alt={client.name}
                                    className="h-10 md:h-12 object-contain opacity-90 hover:opacity-100 transition"
                                />
                            </div>
                        ))}
                    </div>
                </div>
            </section> */}
        </div>
    );
}

export default Certifications;
